import type { PracticeCitation, PracticeQuestion, PracticeVisual, PracticeVisualElement } from '../types';

const createPracticeQuestion = (question: PracticeQuestion): PracticeQuestion => question;

const createVisual = (
  kind: PracticeVisual['kind'],
  title: string,
  description: string,
  elements: PracticeVisualElement[],
): PracticeVisual => ({ kind, title, description, elements });

const createCitation = (
  label: string,
  publisher: string,
  url: string,
  claim: string,
  sourceType: PracticeCitation['sourceType'] = 'official',
): PracticeCitation => ({ label, publisher, url, claim, sourceType });

